// รวมเรื่องค้างเป็นอีเมลฉบับเดียวต่อกองต่อระดับ ค้างครบ 15 วันส่งสำเนาถึงปลัดเทศบาล
const groups = {};
for (const { json: r } of $input.all()) {
  const key = r.department + ':' + r.level;
  groups[key] ??= { to: r.head_email, dept: r.dept_name, level: r.level, rows: [] };
  groups[key].rows.push(r);
}
return Object.values(groups).map(g => ({ json: {
  to: g.to,
  cc: g.level >= 15 ? 'palad@bansuan.test' : '',
  subject: `เรื่องค้างครบ ${g.level} วัน ${g.rows.length} เรื่อง (${g.dept})`,
  body: `เรียน หัวหน้า${g.dept}\n\nเรื่องต่อไปนี้ส่งถึงกองแล้วยังไม่ปิดเรื่อง\n\n` +
        g.rows.map(r => `${r.ticket_no} [${r.urgency}] ${r.subject} ค้าง ${r.age_days} วัน`).join('\n') +
        '\n\nเมื่อดำเนินการเสร็จ กรุณาแจ้งงานสารบรรณเพื่อปิดเรื่อง',
  level: g.level,
  ids: g.rows.map(r => r.id).join(','),
} }));

// รายงานรายสัปดาห์ถึงปลัดเทศบาล
const rows = $input.all().map(i => i.json);
const lines = rows.map(r => `${r.dept_name}: รับใหม่ ${r.assigned_week} ปิดแล้ว ${r.closed_week} ค้าง ${r.open_now} (เกินกำหนด ${r.overdue_now})`);
const total = rows.reduce((s, r) => s + Number(r.overdue_now), 0);
return [{ json: {
  subject: `รายงานเรื่องรับประจำสัปดาห์ เกินกำหนด ${total} เรื่อง`,
  body: 'เรียน ปลัดเทศบาล\n\nสรุปเรื่องรับย้อนหลัง 7 วัน แยกตามกอง\n\n' + lines.join('\n') +
        '\n\nเรื่องที่ยังไม่คัดแยกหรือรอเจ้าหน้าที่ยืนยัน ดูได้ที่ตาราง citizen_requests สถานะ new, triaged และ returned',
} }];
